import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<CurrencyPage> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;

  bool _hasMore = true;

  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();

    _loadNextPage(currencyRepository, 0);
  }

  Future<void> _loadNextPage(CurrencyRepository repository, int page) async {
    setState(() {
      _currencyListFuture = repository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: page),
      );
    });

    final CurrencyPage result = await _currencyListFuture;

    if (!mounted) return;

    setState(() {
      if (page == 0) {
        _allCurrencies = result.items;
      } else {
        _allCurrencies.addAll(result.items);
      }
      _currentPage = page + 1;
      _hasMore = result.hasMore;
    });

    if (page == 0) {
      _filteredCurrenciesNotifier.value = result.items;
      _fadeController.forward(); // запускаем анимацию
    } else {
      final List<CurrencyModel> filtered = _applyFilter(_allCurrencies, _searchQuery);
      _filteredCurrenciesNotifier.value = filtered;
    }

    repository.saveCurrencyList(result.items);
  }

  List<CurrencyModel> _applyFilter(List<CurrencyModel> all, String query) {
    final String lowerQuery = query.toLowerCase();
    if (lowerQuery.isEmpty) return all.toList(growable: false);

    final Iterable<CurrencyModel> result = all.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    return result.toList(growable: false);
  }

  void _filterCurrencies(String query) {
    setState(() {
      _searchQuery = query;
    });

    final List<CurrencyModel> filtered = _applyFilter(_allCurrencies, query);
    _filteredCurrenciesNotifier.value = filtered;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<CurrencyPage>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<CurrencyPage> snapshot) {
          if (!snapshot.hasData) return const SizedBox.shrink();

          final List<CurrencyModel>? data = snapshot.data?.items;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> filteredData, _) {
                      return Column(
                        children: [
                          Expanded(
                            child: ListView.builder(
                              itemCount: filteredData.length,
                              itemBuilder: (BuildContext context, int index) {
                                final CurrencyModel currency = filteredData[index];

                                return Padding(
                                  key: ValueKey(currency.id),
                                  padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                                  child: CurrencyCard(model: currency),
                                );
                              },
                              padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                            ),
                          ),
                        ],
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
      bottomSheet: _hasMore
          ? Container(
              padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 22),
              child: Center(
                child: TextButton(
                  onPressed: () => _loadNextPage(context.read<CurrencyRepository>(), _currentPage - 1),
                  child: Text(context.loc.showMore),
                ),
              ),
            )
          : null,
    );
  }
}
